import { expect, test } from '@rstest/core';
import {
  comma,
  covered,
  uncovered,
  inlined,
  inlinedValue,
  inlinedUncovered,
  // @ts-expect-error Generated by the coverage sourcemap e2e test.
} from '../test-temp-merged/index.js';

test('runs the minified module', () => {
  const logs: string[] = [];
  covered((message: string) => logs.push(message));
  comma((message: string) => logs.push(message));
  inlined((value: string | (() => void)) => {
    if (typeof value === 'string') logs.push(value);
  });
  inlinedValue((message: string) => logs.push(message));
  // Keep the uncalled function in the bundle for coverage collection.
  expect(uncovered).toBeTypeOf('function');
  expect(inlinedUncovered).toBeTypeOf('function');
  expect(logs).toEqual([
    'first',
    'second',
    'fifth',
    'sixth',
    'afterCallback',
    'returned',
  ]);
});
